<?php
/**
 * Bricks' regenerate, recorded — so the suite can prove nothing here ever calls it.
 *
 * @package ADVCM
 */

namespace Bricks;

class Assets_Files {

	public static function regenerate_css_files() {
		vendor_called( 'Bricks\Assets_Files::regenerate_css_files' );
	}

	public static function regenerate_css_file( $data = false, $index = false, $return = false ) {
		vendor_called( 'Bricks\Assets_Files::regenerate_css_file', array( $index ) );
	}
}
